ee:variables.ee:set-variable:
%dw 2.0
output application/java
var t = vars.target
---
flatten([
  if (isEmpty(t.host)) ["host is required"] else [],
  if ((t.host contains "://") or (t.host contains "/") or (t.host contains "@") or (t.host contains "?")) ["host must be a hostname or IP address without a scheme, path, user-info, or query"] else [],
  if (t.port < 1 or t.port > 65535 or t.port != floor(t.port)) ["port must be an integer from 1 through 65535"] else [],
  if (!(t.path startsWith "/") or (t.path startsWith "//") or (t.path contains "\r") or (t.path contains "\n")) ["path must start with one slash and contain no CR/LF"] else [],
  if (!(t.method == "GET" or t.method == "HEAD")) ["method must be GET or HEAD"] else [],
  if (!(t.trustProfile == "default" or t.trustProfile == "corporate")) ["trustProfile must be default or corporate"] else []
])
